draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // old man
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // fishing rod
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2, H/2 + 100 + 20*Math.sin(t));
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 120 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();

  // sea waves
  ctx.beginPath();
  ctx.moveTo(0, H);
  for (let i = 0; i < W; i++) {
    ctx.lineTo(i, H - 10 - 5*Math.sin(i/50 + t));
  }
  ctx.lineTo(W, H);
  ctx.fillStyle = '#cccccc';
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.stroke();

  ctx.restore();
}
